CREATE TABLE products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,sku VARCHAR(64) NOT NULL,name VARCHAR(150) NOT NULL,slug VARCHAR(180) NOT NULL,summary VARCHAR(500) NULL,description LONGTEXT NULL,price DECIMAL(10,2) NOT NULL,stock_quantity INT UNSIGNED NOT NULL DEFAULT 0,locked_stock INT UNSIGNED NOT NULL DEFAULT 0,cover_image_url VARCHAR(500) NULL,cover_asset_ref VARCHAR(128) NULL,status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',published_at DATETIME(3) NULL,created_by BIGINT UNSIGNED NOT NULL,updated_by BIGINT UNSIGNED NOT NULL,deleted_at DATETIME(3) NULL,deleted_by BIGINT UNSIGNED NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT pk_products PRIMARY KEY(id),CONSTRAINT uq_products_sku UNIQUE(sku),CONSTRAINT uq_products_slug UNIQUE(slug),CONSTRAINT fk_products_created FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_products_updated FOREIGN KEY(updated_by) REFERENCES users(id),CONSTRAINT fk_products_deleted FOREIGN KEY(deleted_by) REFERENCES users(id),CONSTRAINT chk_products_status CHECK(status IN ('DRAFT','PUBLISHED','WITHDRAWN')),INDEX idx_products_visibility(status,deleted_at,published_at,id));
CREATE TABLE carts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT pk_carts PRIMARY KEY(id),CONSTRAINT uq_carts_user UNIQUE(user_id),CONSTRAINT fk_carts_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE cart_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,cart_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT pk_cart_items PRIMARY KEY(id),CONSTRAINT uq_cart_items UNIQUE(cart_id,product_id),CONSTRAINT fk_cart_items_cart FOREIGN KEY(cart_id) REFERENCES carts(id),CONSTRAINT fk_cart_items_product FOREIGN KEY(product_id) REFERENCES products(id));
